from pysat.solvers import Glucose42
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

W, G, S = 5, 10, 4
N = G * S  # 40

vpool = IDPool()
def V(w, p, g):
    return vpool.id(('x', w, p, g))

solver = Glucose42()

# Each golfer in exactly one group per week
for w in range(W):
    for p in range(N):
        lits = [V(w,p,g) for g in range(G)]
        cnf = CardEnc.equals(lits, bound=1, vpool=vpool, encoding=EncType.pairwise)
        for c in cnf.clauses:
            solver.add_clause(c)

# Each group has exactly S players
for w in range(W):
    for g in range(G):
        lits = [V(w,p,g) for p in range(N)]
        cnf = CardEnc.equals(lits, bound=S, vpool=vpool, encoding=EncType.seqcounter)
        for c in cnf.clauses:
            solver.add_clause(c)

# Pair meets at most once: for each pair p<q, sum over w,g of (V(w,p,g) AND V(w,q,g)) <= 1
# Introduce m[w,p,q] = meet in week w. m iff exists g with both in g.
# Use aux: y[w,p,q,g] = V(w,p,g) AND V(w,q,g). Then sum_{w,g} y <=1.
# Actually simpler: for each w,p<q, introduce meet[w,p,q] and constrain.
# But we can skip meet variable: sum over w of (OR over g of AND) <=1
# Use indicator: for each w,g,p<q, if both in g then they meet in w. 
# Define m_wpq = OR_g (V(w,p,g) AND V(w,q,g)). Since in each week exactly one g has both iff they meet.
# Simpler approach: for each pair p<q, at most one week where they share a group.
# Use: for pair(p,q), create z[w] = 1 if they share a group in week w.
# z[w] <-> OR_g (V(w,p,g) & V(w,q,g))
# Then sum z[w] <= 1.

for p in range(N):
    for q in range(p+1, N):
        zs = []
        for w in range(W):
            z = vpool.id(('z', w, p, q))
            zs.append(z)
            # z <-> OR_g (V(w,p,g) AND V(w,q,g))
            # Define a_wg = V(w,p,g) & V(w,q,g)
            avars = []
            for g in range(G):
                a = vpool.id(('a', w, p, q, g))
                avars.append(a)
                # a -> V(w,p,g); a -> V(w,q,g); V(w,p,g) & V(w,q,g) -> a
                solver.add_clause([-a, V(w,p,g)])
                solver.add_clause([-a, V(w,q,g)])
                solver.add_clause([a, -V(w,p,g), -V(w,q,g)])
            # z <-> OR avars
            for a in avars:
                solver.add_clause([-a, z])
            solver.add_clause([-z] + avars)
        # sum zs <=1
        cnf = CardEnc.atmost(zs, bound=1, vpool=vpool, encoding=EncType.seqcounter)
        for c in cnf.clauses:
            solver.add_clause(c)

# Symmetry: golfer 0 in group 0 each week; golfers 0..3 in group 0 in week 0.
for w in range(W):
    solver.add_clause([V(w, 0, 0)])
for p in range(4):
    solver.add_clause([V(0, p, 0)])
# Week 0: golfers 4..7 in group 1, etc.
for g in range(G):
    for i in range(S):
        solver.add_clause([V(0, g*S+i, g)])

print("Solving...")
import time
t=time.time()
res = solver.solve()
print("time", time.time()-t, "res", res)
if res:
    model = set(solver.get_model())
    out = [0]*(W*N)
    for w in range(W):
        for p in range(N):
            for g in range(G):
                if V(w,p,g) in model:
                    out[w*N+p] = g
    print(out)
    # Verify
    for w in range(W):
        groups = {}
        for p in range(N):
            groups.setdefault(out[w*N+p], []).append(p)
        assert len(groups)==G and all(len(v)==S for v in groups.values()), groups
    pairs = set()
    for w in range(W):
        groups = {}
        for p in range(N):
            groups.setdefault(out[w*N+p], []).append(p)
        for gp in groups.values():
            for i in range(len(gp)):
                for j in range(i+1,len(gp)):
                    pair = (gp[i],gp[j])
                    assert pair not in pairs, pair
                    pairs.add(pair)
    print("Verified")
